import { html } from "lit";
import { AppPantry } from "../components/pantry.jsx";
import {PantryFilter} from "../components/pantry-filter.js";

export default function PantryPage({ currentPath }) {
  let selectedFilter = "all";
  
  const onFilterChange = (e) => {
    selectedFilter = e.detail;
    document.querySelector("app-pantry").filterType = selectedFilter;
  };

  return html`

  <!--Main Content-->
    <div class="section properties" style="margin-bottom:48px; margin-top:48px;">
      <div class="container">
        <!-- <add-item-button></add-item-button> -->

      <!--Search / filter-->
        <pantry-filter
          @filter-change=${onFilterChange}
        ></pantry-filter>

      <!--Groups-->
          <app-pantry .filterType=${selectedFilter}></app-pantry>

        <div class="section"></div>
      </div>
    </div>
  `;
}